import { QueryClient } from '@tanstack/react-query';

const queryClient = new QueryClient();

const fetchUser = async (id: number) => {
  const response = await fetch(`https://api.example.com/users/${id}`);
  return response.json();
};

// ensureQueryData: returns cached data if available, otherwise fetches
const userData = await queryClient.ensureQueryData({
  queryKey: ['user', 1],
  queryFn: () => fetchUser(1),
});

// fetchQuery: always fetches and returns data
const freshData = await queryClient.fetchQuery({
  queryKey: ['user', 2],
  queryFn: () => fetchUser(2),
});

// prefetchQuery: fetches and caches but returns void
await queryClient.prefetchQuery({
  queryKey: ['user', 3],
  queryFn: () => fetchUser(3),
});

import { QueryClient } from '@tanstack/react-query';

