try { schema.parse({ username: 123, age: 30, active: true }); } catch (e) { console.log(e.errors); } // invalid_type_error
try { schema.parse({ username: "alice", age: 30, active: "yes" }); } catch (e) { console.log(e.errors); } // errorMap

import { z } from 'zod';

const schema = z.object({
  name: z.string(),
  age: z.number(),
});

// Custom error map replaces errorMap, invalid_type_error, and required_error options
const result = schema.safeParse(
  { name: 123 },
  {
    errorMap: (issue, ctx) => {
      if (issue.code === z.ZodIssueCode.invalid_type) {
        if (issue.received === 'undefined') {
          return { message: 'Field is required' }; // replaces required_error
        }
        return { message: 'Invalid type provided' }; // replaces invalid_type_error
      }
      return { message: ctx.defaultError }; // replaces general errorMap
    }
  }
);

