import { tool } from 'ai';
import { z } from 'zod';

const weatherTool = tool({
  description: 'Get the current weather for a location',
  parameters: z.object({
    location: z.string().describe('City name'),
    unit: z.enum(['celsius', 'fahrenheit']).default('celsius')
  }),
  execute: async ({ location, unit }) => {
    return {
      location,
      temperature: 72,
      condition: 'sunny',
      unit
    };
  },
  experimental_toToolResultContent: (result) => {
    return [
      {
        type: 'text' as const,
        text: `Weather in ${result.location}: ${result.temperature}°${result.unit[0].toUpperCase()}, ${result.condition}`
      }
    ];
  }
});

import { tool } from 'ai';
import { z } from 'zod';

// In v7.0.142: 'parameters' → 'schema', 'experimental_toToolResultContent' removed
const weatherTool = tool({
  description: 'Get the weather for a location',
  schema: z.object({
    location: z.string().describe('City name'),
    units: z.enum(['celsius', 'fahrenheit']).optional(),
  }),
  execute: async ({ location, units = 'celsius' }) => {
    // The return value directly becomes the tool result content
    // (replaces experimental_toToolResultContent)
    return {
      location,
      temperature: 22,
      units,
      condition: 'sunny',
    };
  },
});
